,result2={{type="doc",args={"YEL灵猴：去后山找找，应该能见到史书作者。她心里一直挂着修书的事。NOR"}},{type="mapstatustags",args={"520002",1}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL灵猴：去后山找找，应该能见到她。NOR"}}},caozuoName4="给予",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL灵猴：呵呵，他们重新恢复信心了啊，看来江湖的故事还是会继续下去。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL灵猴：来来来少侠，我们边吃边看啊，今天是烤乳猪……嗯嗯，这次更新还挺多的。NOR"}},{type="outgame",args={"hdfb2004"}},{type="itemout",args={"2026hdfbrwwp14",1}}},buttonShow5=1,condition5={relation="and",conditions={}},result5={},buttonShow6=1,condition6={relation="and",conditions={}},result6={},autoCondition1={relation="and",conditions={{type="itemgreater",args={"2026hdfbrwwp14",0}}}},autoResult1={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},znqd402={id="znqd402",baseId="rwnpc21",combatid={1,1001},name="冬君",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL冬君：原来是少侠寻到此处来了。我正好在这边遛狗，便同你讲讲史书续卷的事吧。NOR"}},{type="doc",args={"YEL冬君：石碑上写的并不完整。我们时常相伴左右，清楚她背负了莫大压力，你想听我接着说吗？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="点头",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN你点点头，冬君这才松了口气，继续往下讲述。NOR"}},{type="doc",args={"YEL冬君：整理史册一事她殚精竭虑，自从同僚离开后她就孤立无援，终日承受身心双重重压，夜不能眠。NOR"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL冬君：要是想见她，直接去兰园就好。其实我们都知道，她心里一直挂着修书的事，放不下。NOR"}},{type="doc",args={"YEL冬君：你去拓印一张石碑，她大概能明白你的来意。NOR"}},{type="mapstatustags",args={"520003",1}},{type="refresh",args={}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL冬君：拓印完成了？很好。接下来去兰园找叶凡凡，她对史记颇有研究，或许能帮你解读拓片上的内容。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL冬君：我听说你已经找过叶凡凡了？帮她一下吧，那孩子挺可怜的。NOR"}}},buttonShow6=1,condition6={relation="and",conditions={}},result6={},autoCondition1={relation="and",conditions={{type="itemgreater",args={"2026hdfbrwwp08",0}}}},autoResult1={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={{type="mapstatustagscondi",args={"410005",1,"="}},{type="inroom",args={"hdroom0709","hdroom0706"}}}},autoResult2={{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},znqd403={id="znqd403",baseId="rwnpc05",combatid={1,1001},name="叶凡凡",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=0,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL叶凡凡：是少侠啊，找我有什么事吗？NOR"}},{type="doc",args={"YEL叶凡凡：原来如此，想必你是想问史书续卷为何至今未曾刊印。我不想多找借口，只是心中惶恐，实在不敢再贸然落笔。NOR"}},{type="doc",args={"YEL叶凡凡：我力求落笔尽善尽美，却又怕时限紧迫。久而久之便暂且转写江湖轶事、短篇逸话，借此疏解心绪。不过正史我绝不会就此搁置。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="itemout",args={"2026hdfbrwwp08",1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={